/** M07-B4A local Workerd/D1 synthetic split-lot test ONLY; never deploy this schema. */
export const M07_MULTI_CASH_DDL=[
  "CREATE TABLE m07b4_lots(\n tenant_id TEXT NOT NULL,purchase_id TEXT NOT NULL,supplier_id TEXT NOT NULL,\n sku TEXT NOT NULL,lot_id TEXT NOT NULL,purchase_date TEXT NOT NULL,\n source_hash TEXT NOT NULL CHECK(length(source_hash)=64),\n unit_cost_paisa INTEGER NOT NULL CHECK(unit_cost_paisa>=0),\n original_qty INTEGER NOT NULL CHECK(original_qty>0),\n remaining INTEGER NOT NULL CHECK(remaining BETWEEN 0 AND original_qty),\n PRIMARY KEY(tenant_id,lot_id)) STRICT",
  "CREATE TABLE m07b4_cash_returns(\n tenant_id TEXT NOT NULL,return_id TEXT NOT NULL,operation_id TEXT NOT NULL,\n actor_id TEXT NOT NULL,purchase_id TEXT NOT NULL,supplier_id TEXT NOT NULL,\n sku TEXT NOT NULL,source_hash TEXT NOT NULL CHECK(length(source_hash)=64),\n intent_hash TEXT NOT NULL CHECK(length(intent_hash)=64),\n units INTEGER NOT NULL CHECK(units>0),refund_paisa INTEGER NOT NULL CHECK(refund_paisa>0),\n draws_json TEXT NOT NULL CHECK(json_valid(draws_json)),\n reason TEXT NOT NULL CHECK(length(reason)>0 AND length(reason)<=200),\n PRIMARY KEY(tenant_id,return_id),UNIQUE(tenant_id,operation_id)) STRICT",
  "CREATE TABLE m07b4_movements(\n tenant_id TEXT NOT NULL,return_id TEXT NOT NULL,purchase_id TEXT NOT NULL,\n lot_id TEXT NOT NULL,sku TEXT NOT NULL,units_out INTEGER NOT NULL CHECK(units_out>0),\n lot_remaining INTEGER NOT NULL CHECK(lot_remaining>=0),\n balance_stock INTEGER NOT NULL CHECK(balance_stock>=0),\n PRIMARY KEY(tenant_id,return_id,lot_id)) STRICT",
  "CREATE TABLE m07b4_cash_inflows(\n tenant_id TEXT NOT NULL,return_id TEXT NOT NULL,purchase_id TEXT NOT NULL,\n credit_paisa INTEGER NOT NULL CHECK(credit_paisa>0),\n PRIMARY KEY(tenant_id,return_id)) STRICT",
  "CREATE TRIGGER m07b4_cash_guard BEFORE INSERT ON m07b4_cash_returns BEGIN\n SELECT CASE WHEN json_type(NEW.draws_json)<>'array' OR\n  json_array_length(NEW.draws_json) NOT BETWEEN 1 AND 20\n THEN RAISE(IGNORE) END;\n SELECT CASE WHEN EXISTS(\n  SELECT 1 FROM json_each(NEW.draws_json) j\n  WHERE json_type(j.value)<>'object' OR\n   json_type(j.value,'$.lotId')<>'text' OR\n   json_type(j.value,'$.units')<>'integer' OR\n   json_extract(j.value,'$.units')<1 OR\n   length(json_extract(j.value,'$.lotId')) NOT BETWEEN 1 AND 80 OR\n   json_extract(j.value,'$.lotId') GLOB '*[^A-Z0-9-]*' OR\n   (SELECT COUNT(*) FROM json_each(j.value))<>2\n ) THEN RAISE(IGNORE) END;\n SELECT CASE WHEN\n  (SELECT COUNT(DISTINCT json_extract(j.value,'$.lotId')) FROM json_each(NEW.draws_json) j)\n  <>json_array_length(NEW.draws_json) OR\n  (SELECT COALESCE(SUM(json_extract(j.value,'$.units')),0) FROM json_each(NEW.draws_json) j)\n  <>NEW.units\n THEN RAISE(IGNORE) END;\n SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM m05_sessions s\n  WHERE s.tenant_id=NEW.tenant_id AND s.state='Open')\n THEN RAISE(IGNORE) END;\n SELECT CASE WHEN EXISTS(\n  SELECT 1 FROM m07_purchase_cash_returns prior\n  WHERE prior.tenant_id=NEW.tenant_id AND\n   (prior.purchase_id=NEW.purchase_id OR prior.operation_id=NEW.operation_id OR prior.return_id=NEW.return_id)\n  UNION ALL\n  SELECT 1 FROM m07_purchase_credit_returns prior\n  WHERE prior.tenant_id=NEW.tenant_id AND\n   (prior.purchase_id=NEW.purchase_id OR prior.operation_id=NEW.operation_id OR prior.return_id=NEW.return_id)\n ) THEN RAISE(IGNORE) END;\n SELECT CASE WHEN NOT EXISTS(\n  SELECT 1 FROM m05_purchases p\n  JOIN m05_items i ON i.tenant_id=p.tenant_id AND i.purchase_id=p.purchase_id\n    AND i.sku=p.sku AND i.qty=p.qty AND i.unit_cost_paisa=p.unit_cost_paisa\n  JOIN m05_movements source_move ON source_move.tenant_id=p.tenant_id\n    AND source_move.purchase_id=p.purchase_id AND source_move.sku=p.sku\n    AND source_move.units_in=p.qty AND source_move.lot_id='LOT-'||p.purchase_id\n  JOIN m05_lots root ON root.tenant_id=p.tenant_id AND root.purchase_id=p.purchase_id\n    AND root.supplier_id=p.supplier_id AND root.sku=p.sku\n    AND root.lot_id=source_move.lot_id AND root.qty=p.qty\n    AND root.unit_cost_paisa=p.unit_cost_paisa AND root.purchase_date=p.purchase_date\n  JOIN m05_products product ON product.tenant_id=p.tenant_id AND product.sku=p.sku\n    AND product.active=1 AND product.deleted=0 AND product.product_type='Standard'\n  JOIN m05_suppliers supplier ON supplier.tenant_id=p.tenant_id\n    AND supplier.supplier_id=p.supplier_id AND supplier.active=1\n  JOIN m05_party_links link ON link.tenant_id=supplier.tenant_id\n    AND link.source_group='SUPPLIERS' AND link.source_id=supplier.supplier_id\n    AND link.party_id=supplier.party_id AND link.reviewed=1\n  WHERE p.tenant_id=NEW.tenant_id AND p.purchase_id=NEW.purchase_id\n    AND p.supplier_id=NEW.supplier_id AND p.sku=NEW.sku\n    AND p.intent_hash=NEW.source_hash AND p.grand_paisa>0\n    AND p.grand_paisa=p.qty*p.unit_cost_paisa-p.discount_paisa\n    AND p.grand_paisa*NEW.units=NEW.refund_paisa*p.qty\n    AND NEW.units<=p.qty AND product.stock>=NEW.units\n    AND p.paid_paisa>=NEW.refund_paisa+\n      (SELECT COALESCE(SUM(old.credit_paisa),0) FROM m07b4_cash_inflows old\n       WHERE old.tenant_id=p.tenant_id AND old.purchase_id=p.purchase_id)\n    AND (SELECT COUNT(*) FROM m07b4_lots b\n       WHERE b.tenant_id=p.tenant_id AND b.purchase_id=p.purchase_id AND b.sku=p.sku)>=2\n    AND (SELECT COALESCE(SUM(b.original_qty),0) FROM m07b4_lots b\n       WHERE b.tenant_id=p.tenant_id AND b.purchase_id=p.purchase_id AND b.sku=p.sku)=p.qty\n    AND NOT EXISTS(SELECT 1 FROM m07b4_lots b\n       WHERE b.tenant_id=p.tenant_id AND b.purchase_id=p.purchase_id AND\n         (b.sku<>p.sku OR b.supplier_id<>p.supplier_id OR\n          b.source_hash<>p.intent_hash OR b.unit_cost_paisa<>p.unit_cost_paisa OR\n          length(b.purchase_date)<>10))\n ) THEN RAISE(IGNORE) END;\n SELECT CASE WHEN (\n  SELECT COUNT(*) FROM json_each(NEW.draws_json) j\n  JOIN m07b4_lots l ON l.tenant_id=NEW.tenant_id\n    AND l.purchase_id=NEW.purchase_id AND l.supplier_id=NEW.supplier_id\n    AND l.sku=NEW.sku AND l.source_hash=NEW.source_hash\n    AND l.lot_id=json_extract(j.value,'$.lotId')\n    AND l.remaining>=json_extract(j.value,'$.units')\n )<>json_array_length(NEW.draws_json)\n THEN RAISE(IGNORE) END;\n SELECT CASE WHEN EXISTS(\n  SELECT 1 FROM json_each(NEW.draws_json) later_draw\n  JOIN m07b4_lots later ON later.tenant_id=NEW.tenant_id\n    AND later.lot_id=json_extract(later_draw.value,'$.lotId')\n  JOIN json_each(NEW.draws_json) earlier_draw\n    ON CAST(earlier_draw.key AS INTEGER)<CAST(later_draw.key AS INTEGER)\n  JOIN m07b4_lots earlier ON earlier.tenant_id=NEW.tenant_id\n    AND earlier.lot_id=json_extract(earlier_draw.value,'$.lotId')\n  WHERE earlier.purchase_date>later.purchase_date OR\n    (earlier.purchase_date=later.purchase_date AND earlier.lot_id>later.lot_id)\n ) THEN RAISE(IGNORE) END;\n SELECT CASE WHEN EXISTS(\n  SELECT 1 FROM json_each(NEW.draws_json) j\n  JOIN m07b4_lots chosen ON chosen.tenant_id=NEW.tenant_id\n    AND chosen.purchase_id=NEW.purchase_id AND chosen.sku=NEW.sku\n    AND chosen.lot_id=json_extract(j.value,'$.lotId')\n  JOIN m07b4_lots prior ON prior.tenant_id=chosen.tenant_id\n    AND prior.purchase_id=chosen.purchase_id AND prior.sku=chosen.sku\n    AND prior.remaining>0 AND\n      (prior.purchase_date<chosen.purchase_date OR\n       (prior.purchase_date=chosen.purchase_date AND prior.lot_id<chosen.lot_id))\n  LEFT JOIN json_each(NEW.draws_json) used\n    ON json_extract(used.value,'$.lotId')=prior.lot_id\n  WHERE COALESCE(json_extract(used.value,'$.units'),0)<prior.remaining\n ) THEN RAISE(IGNORE) END;\n END",
  "CREATE TRIGGER m07b4_cash_commit AFTER INSERT ON m07b4_cash_returns BEGIN\n UPDATE m07b4_lots SET remaining=remaining-(\n  SELECT json_extract(j.value,'$.units') FROM json_each(NEW.draws_json) j\n  WHERE json_extract(j.value,'$.lotId')=m07b4_lots.lot_id)\n WHERE tenant_id=NEW.tenant_id AND purchase_id=NEW.purchase_id AND sku=NEW.sku\n  AND lot_id IN(SELECT json_extract(j.value,'$.lotId') FROM json_each(NEW.draws_json) j)\n  AND remaining>=(\n   SELECT json_extract(j.value,'$.units') FROM json_each(NEW.draws_json) j\n   WHERE json_extract(j.value,'$.lotId')=m07b4_lots.lot_id);\n SELECT CASE WHEN changes()<>json_array_length(NEW.draws_json)\n  THEN RAISE(ABORT,'m07-b4-stale-original-split-lot') END;\n UPDATE m05_products SET stock=stock-NEW.units,version=version+1\n WHERE tenant_id=NEW.tenant_id AND sku=NEW.sku\n   AND active=1 AND deleted=0 AND product_type='Standard' AND stock>=NEW.units;\n SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'m07-b4-stock-race') END;\n INSERT INTO m07b4_movements\n SELECT NEW.tenant_id,NEW.return_id,NEW.purchase_id,l.lot_id,NEW.sku,\n  json_extract(j.value,'$.units'),l.remaining,p.stock\n FROM json_each(NEW.draws_json) j\n JOIN m07b4_lots l ON l.tenant_id=NEW.tenant_id\n  AND l.purchase_id=NEW.purchase_id AND l.sku=NEW.sku\n  AND l.lot_id=json_extract(j.value,'$.lotId')\n JOIN m05_products p ON p.tenant_id=NEW.tenant_id AND p.sku=NEW.sku;\n SELECT CASE WHEN changes()<>json_array_length(NEW.draws_json)\n  THEN RAISE(ABORT,'m07-b4-movement-incomplete') END;\n INSERT INTO m07b4_cash_inflows\n VALUES(NEW.tenant_id,NEW.return_id,NEW.purchase_id,NEW.refund_paisa);\n SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'m07-b4-cash-missing') END;\n END",
  "CREATE TRIGGER m07b4_guard_old_cash BEFORE INSERT ON m07_purchase_cash_returns BEGIN\n SELECT CASE WHEN EXISTS(SELECT 1 FROM m07b4_cash_returns r\n  WHERE r.tenant_id=NEW.tenant_id AND\n  (r.purchase_id=NEW.purchase_id OR r.return_id=NEW.return_id OR r.operation_id=NEW.operation_id))\n THEN RAISE(IGNORE) END;\n END",
  "CREATE TRIGGER m07b4_guard_old_credit BEFORE INSERT ON m07_purchase_credit_returns BEGIN\n SELECT CASE WHEN EXISTS(SELECT 1 FROM m07b4_cash_returns r\n  WHERE r.tenant_id=NEW.tenant_id AND\n  (r.purchase_id=NEW.purchase_id OR r.return_id=NEW.return_id OR r.operation_id=NEW.operation_id))\n THEN RAISE(IGNORE) END;\n END",
  "CREATE TRIGGER m07b4_cash_immutable_update BEFORE UPDATE ON m07b4_cash_returns BEGIN\n SELECT RAISE(ABORT,'m07-b4-return-immutable'); END",
  "CREATE TRIGGER m07b4_cash_immutable_delete BEFORE DELETE ON m07b4_cash_returns BEGIN\n SELECT RAISE(ABORT,'m07-b4-return-immutable'); END"
];
